CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE,
 display_name VARCHAR(80) NOT NULL, department VARCHAR(100) NOT NULL DEFAULT '', bio VARCHAR(1000) NOT NULL DEFAULT '',
 interests VARCHAR(500) NOT NULL DEFAULT '', role ENUM('student','admin') NOT NULL DEFAULT 'student',
 active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallets (user_id BIGINT UNSIGNED PRIMARY KEY, balance INT NOT NULL DEFAULT 0, held_balance INT NOT NULL DEFAULT 0,
 FOREIGN KEY(user_id) REFERENCES users(id), CHECK(balance >= held_balance AND held_balance >= 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS offers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, teacher_id BIGINT UNSIGNED NOT NULL, skill_id BIGINT UNSIGNED NOT NULL,
 level ENUM('Beginner','Intermediate','Advanced') NOT NULL, mode ENUM('Online','Campus') NOT NULL,
 description VARCHAR(2000) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE,
 UNIQUE(teacher_id,skill_id), FOREIGN KEY(teacher_id) REFERENCES users(id), FOREIGN KEY(skill_id) REFERENCES skills(id), INDEX(skill_id,active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability_slots (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, offer_id BIGINT UNSIGNED NOT NULL,
 start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, status ENUM('AVAILABLE','BOOKED','CLOSED') NOT NULL DEFAULT 'AVAILABLE',
 FOREIGN KEY(offer_id) REFERENCES offers(id), CHECK(end_at=DATE_ADD(start_at,INTERVAL 60 MINUTE)), INDEX(start_at,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, slot_id BIGINT UNSIGNED NOT NULL, learner_id BIGINT UNSIGNED NOT NULL,
 status ENUM('PENDING','CONFIRMED','REJECTED','CANCELLED','DISPUTED','COMPLETED') NOT NULL DEFAULT 'PENDING',
 location VARCHAR(1000) NOT NULL DEFAULT '', requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 occupied_slot BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN status IN ('CONFIRMED','DISPUTED','COMPLETED') THEN slot_id ELSE NULL END) STORED,
 pending_request VARCHAR(80) GENERATED ALWAYS AS (CASE WHEN status='PENDING' THEN CONCAT(slot_id,':',learner_id) ELSE NULL END) STORED,
 UNIQUE(occupied_slot), UNIQUE(pending_request), FOREIGN KEY(slot_id) REFERENCES availability_slots(id), FOREIGN KEY(learner_id) REFERENCES users(id), INDEX(learner_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS completion_confirmations (session_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,confirmed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(session_id,user_id),FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS credit_holds (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,session_id BIGINT UNSIGNED NOT NULL UNIQUE,learner_id BIGINT UNSIGNED NOT NULL,
 amount INT NOT NULL DEFAULT 1,status ENUM('ACTIVE','RELEASED','SETTLED') NOT NULL DEFAULT 'ACTIVE',CHECK(amount=1),
 FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(learner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS credit_transfers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,session_id BIGINT UNSIGNED UNIQUE,payer_id BIGINT UNSIGNED,payee_id BIGINT UNSIGNED NOT NULL,
 amount INT NOT NULL,type ENUM('GRANT','SETTLEMENT') NOT NULL,idempotency_key VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 CHECK((type='GRANT' AND amount=3 AND payer_id IS NULL AND session_id IS NULL) OR (type='SETTLEMENT' AND amount=1 AND payer_id IS NOT NULL AND session_id IS NOT NULL)),
 FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(payer_id) REFERENCES users(id),FOREIGN KEY(payee_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,session_id BIGINT UNSIGNED NOT NULL UNIQUE,rating INT NOT NULL,text VARCHAR(2000) NOT NULL DEFAULT '',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(session_id) REFERENCES sessions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS disputes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,session_id BIGINT UNSIGNED NOT NULL UNIQUE,opened_by BIGINT UNSIGNED NOT NULL,reason VARCHAR(2000) NOT NULL,
 status ENUM('OPEN','RESOLVED') NOT NULL DEFAULT 'OPEN',decision ENUM('SETTLE','CANCEL'),admin_reason VARCHAR(2000),resolved_by BIGINT UNSIGNED,resolved_at DATETIME,
 FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(opened_by) REFERENCES users(id),FOREIGN KEY(resolved_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT UNSIGNED,details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_sessions (token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED,csrf VARCHAR(80) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS otp_challenges (id CHAR(48) PRIMARY KEY,session_hash CHAR(64) NOT NULL,email VARCHAR(254) NOT NULL,code_hash CHAR(64) NOT NULL,profile JSON,
 expires_at DATETIME NOT NULL,attempts INT NOT NULL DEFAULT 0,used BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(email,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY,hits INT NOT NULL,reset_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS captcha_tokens (token_hash CHAR(64) PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS github_connections (user_id BIGINT UNSIGNED PRIMARY KEY,login VARCHAR(100) NOT NULL,encrypted_token TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS github_oauth_states (state_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_imports (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,owner_id BIGINT UNSIGNED NOT NULL,repo VARCHAR(200) NOT NULL UNIQUE,sha CHAR(40) NOT NULL,manifest JSON NOT NULL,status ENUM('VALIDATED','DEPLOYED') NOT NULL DEFAULT 'VALIDATED',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE VIEW popular_skills AS SELECT sk.id,sk.name,sk.category,COUNT(DISTINCT o.id) AS offers,COUNT(DISTINCT CASE WHEN s.status='COMPLETED' THEN s.id END) AS completed_sessions FROM skills sk LEFT JOIN offers o ON o.skill_id=sk.id LEFT JOIN availability_slots a ON a.offer_id=o.id LEFT JOIN sessions s ON s.slot_id=a.id GROUP BY sk.id,sk.name,sk.category;

